using AutoPecasERP.Core.Entities;using AutoPecasERP.Data.Context;using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Services.CRM;
public class CrmService{readonly ErpDbContext _db;public CrmService(ErpDbContext db)=>_db=db;
public async Task<OportunidadeCrm> CriarAsync(int? clienteId,string contato,string telefone,string assunto,decimal valor,string responsavel){var o=new OportunidadeCrm{ClienteId=clienteId,NomeContato=contato,Telefone=telefone,Assunto=assunto,ValorEstimado=valor,Responsavel=responsavel};_db.OportunidadesCrm.Add(o);await _db.SaveChangesAsync();return o;}
public async Task FollowUpAsync(int oportunidadeId,string descricao,string usuario,DateTime? proximo){var o=await _db.OportunidadesCrm.FindAsync(oportunidadeId)??throw new InvalidOperationException("Oportunidade não encontrada.");_db.InteracoesCrm.Add(new InteracaoCrm{OportunidadeCrmId=o.Id,Descricao=descricao,Usuario=usuario,ProximoContato=proximo});o.ProximoContato=proximo;if(o.Etapa=="LEAD")o.Etapa="EM_CONTATO";await _db.SaveChangesAsync();}
public async Task RegistrarPerdaAsync(int? clienteId,int? produtoId,decimal qtd,decimal valor,string motivo,string vendedor,string obs=""){_db.VendasPerdidas.Add(new VendaPerdida{ClienteId=clienteId,ProdutoId=produtoId,Quantidade=qtd,ValorEstimado=valor,Motivo=motivo,Vendedor=vendedor,Observacao=obs});await _db.SaveChangesAsync();}
public async Task<List<ClienteInativoDto>> ClientesInativosAsync(int dias=90){var limite=DateTime.Now.AddDays(-dias);var clientes=await _db.Clientes.Where(x=>x.Ativo).ToListAsync();var ultimas=await _db.Vendas.GroupBy(x=>x.ClienteId).Select(g=>new{ClienteId=g.Key,Ultima=g.Max(x=>x.Data)}).ToListAsync();return clientes.Select(c=>new ClienteInativoDto(c.Id,c.Nome,ultimas.FirstOrDefault(x=>x.ClienteId==c.Id)?.Ultima)).Where(x=>x.UltimaCompra==null||x.UltimaCompra<limite).OrderBy(x=>x.UltimaCompra).ToList();}}
public record ClienteInativoDto(int ClienteId,string Nome,DateTime? UltimaCompra);